import{_ as e,o as n,c as a,ak as r}from"./chunks/framework.CMX7UUIo.js";const p=JSON.parse('{"title":"Wheat Processing","description":"","frontmatter":{"title":"Wheat Processing"},"headers":[],"relativePath":"en/crops/wheat/processing.md","filePath":"en/crops/wheat/processing.md"}'),t={name:"en/crops/wheat/processing.md"};function o(s,i,l,g,d,c){return n(),a("div",null,[...i[0]||(i[0]=[r('<h1 id="wheat-processing" tabindex="-1">Wheat Processing <a class="header-anchor" href="#wheat-processing" aria-label="Permalink to “Wheat Processing”">​</a></h1><p>Wheat processing is the process of removing impurities from wheat, followed by blending, moisture adjustment, crushing, bran removal, purification, grinding, and sieving to produce wheat flour with minimal bran content. The processing method is a key factor affecting the technical performance and final product quality of wheat flour.</p><h2 id="intake-and-pre-cleaning" tabindex="-1">Intake and Pre-cleaning <a class="header-anchor" href="#intake-and-pre-cleaning" aria-label="Permalink to “Intake and Pre-cleaning”">​</a></h2><p>The first step in wheat processing is <strong>intake and pre-cleaning</strong>, aimed at removing large impurities, light debris, and dust from the raw grain, creating favorable conditions for subsequent cleaning processes.</p><h3 id="raw-wheat-receiving" tabindex="-1">Raw Wheat Receiving <a class="header-anchor" href="#raw-wheat-receiving" aria-label="Permalink to “Raw Wheat Receiving”">​</a></h3><p>After wheat arrives at the flour mill from various regions, it enters the receiving system. The receiving process includes:</p><ul><li><strong>Automatic weighing</strong>: Recording the quantity of wheat entering the mill</li><li><strong>Initial inspection</strong>: Testing basic indicators such as moisture, bulk density, and impurity content</li><li><strong>Temporary storage</strong>: Storing in raw wheat bins according to quality classification</li></ul><h3 id="pre-cleaning" tabindex="-1">Pre-cleaning <a class="header-anchor" href="#pre-cleaning" aria-label="Permalink to “Pre-cleaning”">​</a></h3><p>Pre-cleaning primarily removes <strong>large impurities</strong> and <strong>light debris</strong> from wheat:</p><ul><li><strong>Screening</strong>: Using vibrating sifters or planar rotary sifters to remove impurities larger than wheat (such as straw, soil clumps)</li><li><strong>Air separation</strong>: Using airflow to separate light debris (such as husks, dust)</li><li><strong>Magnetic separation</strong>: Removing magnetic metal impurities</li></ul><h2 id="cleaning-and-conditioning" tabindex="-1">Cleaning and Conditioning <a class="header-anchor" href="#cleaning-and-conditioning" aria-label="Permalink to “Cleaning and Conditioning”">​</a></h2><p>Cleaning and conditioning is the most critical preparation process before wheat milling, directly affecting flour quality and extraction rate.</p><h3 id="wet-cleaning" tabindex="-1">Wet Cleaning <a class="header-anchor" href="#wet-cleaning" aria-label="Permalink to “Wet Cleaning”">​</a></h3><p><strong>Washing machine</strong> is the core equipment for wet cleaning, with main functions:</p><ul><li>Soaking wheat to soften surface impurities</li><li>Removing stones (sand and gravel similar in size to wheat grains)</li><li>Adjusting wheat moisture</li><li>Killing some microorganisms</li></ul><h3 id="dry-cleaning" tabindex="-1">Dry Cleaning <a class="header-anchor" href="#dry-cleaning" aria-label="Permalink to “Dry Cleaning”">​</a></h3><ul><li><strong>Wheat scourer</strong>: Removing dust, microorganisms, and embedded impurities from the grain surface through impact</li><li><strong>Gravity separator</strong>: Removing different grain varieties such as buckwheat and wild peas based on seed length differences</li><li><strong>Wheat brush</strong>: Cleaning impurities from wheat grooves</li></ul><h3 id="moisture-conditioning" tabindex="-1">Moisture Conditioning <a class="header-anchor" href="#moisture-conditioning" aria-label="Permalink to “Moisture Conditioning”">​</a></h3><p><strong>Water adder</strong> is used to precisely control wheat moisture:</p><ul><li>Adding appropriate water based on original wheat moisture and target flour moisture</li><li>Winter water temperature generally controlled at 35-45°C to promote moisture penetration</li><li>After water addition, wheat needs to rest for 6-8 hours for moisture to evenly penetrate the grain interior</li></ul><h3 id="blending" tabindex="-1">Blending <a class="header-anchor" href="#blending" aria-label="Permalink to “Blending”">​</a></h3><p>Wheat from different origins and varieties has significant quality differences, requiring <strong>blending</strong>:</p><ul><li>Adjusting protein content to ensure stable flour quality</li><li>Balancing gluten quality and ash content</li><li>Optimizing costs and improving economic benefits</li></ul><h2 id="milling" tabindex="-1">Milling <a class="header-anchor" href="#milling" aria-label="Permalink to “Milling”">​</a></h2><p>Milling is the core环节 of wheat processing, using physical methods to separate and grind various parts of the grain into flour.</p><h3 id="cleaning-process" tabindex="-1">Cleaning Process <a class="header-anchor" href="#cleaning-process" aria-label="Permalink to “Cleaning Process”">​</a></h3><ol><li><strong>Break system</strong>: Handling the separation of bran and endosperm</li><li><strong>Reduction system</strong>: Fine grinding of endosperm to obtain fine white flour</li><li><strong>Grinding system</strong>: Handling wheat middlings to further extract endosperm</li><li><strong>Tail system</strong>: Handling end materials of bran to extract remaining endosperm</li></ol><h3 id="main-equipment" tabindex="-1">Main Equipment <a class="header-anchor" href="#main-equipment" aria-label="Permalink to “Main Equipment”">​</a></h3><table tabindex="0"><thead><tr><th>Equipment</th><th>Function</th></tr></thead><tbody><tr><td><strong>Roller mill</strong></td><td>Using roller extrusion and shearing to grind endosperm into flour</td></tr><tr><td><strong>Plansifter</strong></td><td>Sieving flour and bran of different particle sizes</td></tr><tr><td><strong>Purifier</strong></td><td>Using airflow and sieving to purify middlings, improving flour quality</td></tr><tr><td><strong>Bran finisher</strong></td><td>Separating flour adhering to bran</td></tr></tbody></table><h3 id="grinding-system" tabindex="-1">Grinding System <a class="header-anchor" href="#grinding-system" aria-label="Permalink to “Grinding System”">​</a></h3><p>Modern milling uses <strong>multi-pass grinding</strong> processes, typically including:</p><ul><li>4-5 breaks</li><li>6-8 reductions</li><li>2-3 grindings</li><li>1-2 tail passes</li></ul><p>Each grinding pass requires sieving and classification to achieve proper material distribution.</p><h2 id="flour-post-treatment" tabindex="-1">Flour Post-treatment <a class="header-anchor" href="#flour-post-treatment" aria-label="Permalink to “Flour Post-treatment”">​</a></h2><h3 id="flour-blending" tabindex="-1">Flour Blending <a class="header-anchor" href="#flour-blending" aria-label="Permalink to “Flour Blending”">​</a></h3><p>According to different usage requirements, flour from various systems is precisely <strong>blended</strong>:</p><ul><li>Adjusting protein content and quality</li><li>Controlling ash indicators</li><li>Optimizing whiteness and gluten strength</li></ul><h3 id="aging" tabindex="-1">Aging <a class="header-anchor" href="#aging" aria-label="Permalink to “Aging”">​</a></h3><p>Freshly milled flour needs <strong>resting and aging</strong>:</p><ul><li>Allowing gluten proteins to fully oxidize, improving dough rheological properties</li><li>Promoting stability of enzyme activity</li><li>Improving flour baking performance</li></ul><p>Aging time is typically 1-3 days, with temperature controlled at 20-25°C.</p><h3 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to “Storage”">​</a></h3><p>Flour storage conditions require:</p><ul><li><strong>Temperature</strong>: Controlled below 20°C to prevent insect infestation and mold</li><li><strong>Humidity</strong>: Relative humidity not exceeding 70% to prevent caking</li><li><strong>Ventilation</strong>: Maintaining air circulation to avoid odor absorption</li><li><strong>Light protection</strong>: Preventing light-induced pigment oxidation and discoloration</li></ul><h3 id="packaging" tabindex="-1">Packaging <a class="header-anchor" href="#packaging" aria-label="Permalink to “Packaging”">​</a></h3><p><strong>Graded packaging</strong> according to different market demands:</p><ul><li>Retail packaging: 1kg, 2.5kg, 5kg small packages</li><li>Wholesale packaging: 10kg, 25kg woven bags</li><li>Bulk: Direct delivery to food processing plants</li></ul><p>The packaging process must strictly control <strong>metal detection</strong> and <strong>weight inspection</strong>.</p><h2 id="by-product-processing" tabindex="-1">By-product Processing <a class="header-anchor" href="#by-product-processing" aria-label="Permalink to “By-product Processing”">​</a></h2><p>Various by-products are generated during wheat processing:</p><ul><li><strong>Bran</strong>: The outer epidermis of wheat, rich in dietary fiber and B vitamins, mainly used as feed</li><li><strong>Middlings</strong>: The transitional product between bran and flour, can be used for feed or food additives</li><li><strong>Germ</strong>: The embryonic part of wheat, high nutritional value, can be extracted for germ oil or used as food raw material</li></ul>',51)])])}const u=e(t,[["render",o]]);export{p as __pageData,u as default};
